import { getQualityTier, TIER } from './qualityTier';

/**
 * Derived PBR maps for the planet albedos.
 *
 * Normal maps are generated by scripts/deriveNormalMaps.mjs and committed
 * alongside the albedos. The sun is deliberately absent: it renders emissive,
 * where a normal map has no meaning.
 */

// Kept in sync with the script's output. An explicit set rather than probing
// for the file, so a missing map is a no-op instead of a 404 mid-render.
const HAS_NORMAL = new Set([
  'earth', 'jupiter', 'mars', 'mercury', 'saturn', 'venus',
]);

/**
 * Per-planet roughness. Every material in the scene used a flat 0.7, which is
 * why the bodies read as the same substance painted different colours. These
 * are scalars rather than maps: one value per body gets most of the benefit for
 * no extra texture bandwidth.
 */
const ROUGHNESS = {
  mercury: 0.94,  // airless, dusty regolith — almost no specular
  mars:    0.88,
  venus:   0.72,  // thick cloud deck, softly glossy
  earth:   0.65,  // oceans pull the average down
  jupiter: 0.58,  // gas, smooth highlight across the bands
  saturn:  0.58,
  uranus:  0.50,
  neptune: 0.50,
  sun:     1.00,
};

/**
 * Per-body atmosphere. Colour is roughly what that body's sky actually
 * scatters, and strength stands in for how much of one it has.
 *
 * Mercury is deliberately absent: it has no atmosphere, so it should have no
 * rim. The Sun is absent because it is emissive and already carries its own
 * corona.
 */
const ATMOSPHERE = {
  // Shells are generous and the exponents low on purpose. A tight, high-contrast
  // band sits right on the silhouette and reads as an outline stroke; a wider,
  // softer gradient that fades outward reads as air.
  earth:   { color: '#7fc4ff', strength: 0.34, scale: 1.085, power: 3.4 },
  venus:   { color: '#ffd49a', strength: 0.40, scale: 1.100, power: 3.0 },  // thick, hazy
  mars:    { color: '#ff9d6e', strength: 0.15, scale: 1.050, power: 3.8 },  // thin and dusty
  jupiter: { color: '#ffd2a6', strength: 0.27, scale: 1.070, power: 3.5 },
  saturn:  { color: '#ffe2ae', strength: 0.25, scale: 1.070, power: 3.5 },
  uranus:  { color: '#9ee4ff', strength: 0.30, scale: 1.085, power: 3.2 },
  neptune: { color: '#7b9fff', strength: 0.34, scale: 1.085, power: 3.2 },
};

/** Atmosphere config for a body, or null if it should not have one. */
export function atmosphereFor(albedoUrl) {
  const n = bodyName(albedoUrl);
  return (n && ATMOSPHERE[n]) ? ATMOSPHERE[n] : null;
}

function bodyName(url) {
  const m = /\/textures\/([a-z]+)\.webp(?:$|\?)/.exec(url || '');
  return m ? m[1] : null;
}

/**
 * Tier-aware albedo path. Low and medium get the half-resolution variant: a 4x
 * cut in GPU memory and upload time for detail that is not resolvable at the
 * size these bodies render. High keeps the original.
 *
 * Resolve this only at the point of loading — everything else (roughnessFor,
 * normalMapFor) keys off the canonical URL, so passing a resolved one around
 * would stop those matching.
 *
 * Callers pass a tier they froze at first render, matching how they already
 * freeze the normal-map decision: if a later probe step-down changed the URL
 * mid-session, the body would re-suspend and pop.
 */
export function albedoFor(albedoUrl, tier = getQualityTier()) {
  if (tier >= TIER.HIGH) return albedoUrl;
  const n = bodyName(albedoUrl);
  return n ? `/textures/${n}_lo.webp` : albedoUrl;
}

/** Path to the derived normal map, or null if this body has none. */
export function normalMapFor(albedoUrl) {
  const n = bodyName(albedoUrl);
  return n && HAS_NORMAL.has(n) ? `/textures/${n}_n.webp` : null;
}

/**
 * Roughness for procedurally-textured bodies, which have no URL to key on.
 * Same idea as ROUGHNESS above: one scalar per surface type, no extra texture.
 */
export const TYPE_ROUGHNESS = {
  rocky: 0.92,   // dry, dusty, effectively no specular
  icy:   0.45,   // ice is the one genuinely glossy surface out there
  alien: 0.70,
};

/** Per-body roughness, falling back to the previous flat value. */
export function roughnessFor(albedoUrl, fallback = 0.7) {
  const n = bodyName(albedoUrl);
  return (n && ROUGHNESS[n] !== undefined) ? ROUGHNESS[n] : fallback;
}
